pub mod double;
pub mod quad;

pub use double::double;
pub use quad::quadruple;

#[cfg(test)]
mod contract_tests;

/// Returns `x * 2`.
pub fn double(x: i64) -> i64 {
    x * 2
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn doubles_positive_negative_and_zero() {
        assert_eq!(double(21), 42);
        assert_eq!(double(-3), -6);
        assert_eq!(double(0), 0);
    }
}

