/// Returns `double(double(x))`, i.e. `x * 4`.
pub fn quadruple(x: i64) -> i64 {
    crate::double::double(crate::double::double(x))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn quadruples_positive_negative_and_zero() {
        assert_eq!(quadruple(5), 20);
        assert_eq!(quadruple(-3), -12);
        assert_eq!(quadruple(0), 0);
    }
}

