//! Contract tests binding the `quad` consumer to the `double` producer interface.

#[test]
fn double_multiplies_by_two() {
    assert_eq!(crate::double::double(21), 42);
    assert_eq!(crate::double::double(-7), -14);
    assert_eq!(crate::double::double(0), 0);
}

#[test]
fn quadruple_is_double_composed_with_double() {
    assert_eq!(crate::quad::quadruple(5), 20);
    assert_eq!(crate::quad::quadruple(-2), -8);
}
